insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('F-01','إغلاق غرفة أو عيادة أو منطقة للصيانة وإعادة فتحها','FAC','["MNT", "FAC", "BEN", "DIR", "BME", "IT", "GEN"]'::jsonb,'لا تُغلق مساحة تشغيلية إلا بخطة معلنة وبديل متفق عليه للمرضى، ولا تعود إلى الخدمة إلا بفحص مشترك موثّق يثبت سلامتها ونظافتها وجاهزية أنظمتها.','أعمال صيانة مخططة أو تصحيحية أو تطوير تتطلب إخلاء غرفة أو عيادة أو منطقة، أو عطل يجعل المساحة غير آمنة للاستخدام.','نطاق الأعمال، أرقام الغرف المتأثرة، المدة المقدّرة، الأنظمة التي ستُعزل، تصنيف المنطقة (حرجة/غير حرجة).','إشعار إغلاق معتمد، لوحة «مغلق للصيانة» في الموقع، حالة الغرفة محدّثة في السجل، محضر إعادة فتح موقّع.','الالتزام بمدة الإغلاق المعلنة ≥ 90٪؛ صفر إعادة فتح دون محضر؛ متوسط مدة الإغلاق لكل نوع عمل.','[{"unit": "MNT", "action": "رفع طلب الإغلاق: نطاق العمل، الغرف المتأثرة بأرقامها، المدة المقدّرة، الأنظمة التي ستُعزل، وهل يلزم تصريح عمل (M-01)", "sla": "قبل 5 أيام عمل للمخطط", "where": "نموذج طلب إغلاق", "kind": "step", "role": "مشرف الصيانة أو مهندس المشروع"}, {"unit": "FAC", "action": "تصنيف الإغلاق: جزئي أو كلي، مخطط أو طارئ، منطقة حرجة أم لا، وتحديد مستوى الاعتماد وفق R-12", "sla": "يوم عمل", "where": "سجل المساحات", "kind": "decision"}, {"unit": "BEN", "action": "الاتفاق على موعد الإغلاق والبديل: نقل العيادة، إعادة جدولة المواعيد، أو تشغيل غرفة احتياطية", "sla": "يومان", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "BEN", "action": "تقييم مخاطر العدوى (ICRA) وتحديد الفئة ومتطلبات العزل والحواجز والضغط السلبي إن لزم", "sla": "يومان", "where": "نموذج ICRA", "kind": "step", "role": "مكافحة العدوى"}, {"unit": "DIR", "action": "اعتماد الإغلاق إذا تجاوز يومي عمل أو كان في منطقة حرجة (R-12)", "sla": "يوم عمل", "where": "—", "kind": "decision"}, {"unit": "FAC", "action": "إصدار إشعار الإغلاق للمنشأة والأقسام المعنية والأمن، وتحديث حالة الغرفة إلى «مغلقة للصيانة» بتاريخ العودة المتوقع", "sla": "قبل الإغلاق بـ 48 ساعة", "where": "سجل المساحات", "kind": "step"}, {"unit": "BME", "action": "إخلاء الأجهزة الطبية أو حمايتها في مكانها، وتوثيق مواقعها المؤقتة", "sla": "قبل الإغلاق", "where": "سجل الأجهزة", "kind": "step"}, {"unit": "IT", "action": "فصل الأجهزة والنقاط التقنية أو حمايتها", "sla": "قبل الإغلاق", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "إخلاء الأثاث والمستلزمات، وتركيب الحواجز ولوحة «مغلق للصيانة» بتاريخ العودة المتوقع", "sla": "يوم الإغلاق", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تنفيذ الأعمال بتصريح عمل وعزل آمن (M-01)، وتحديث التقدم يومياً، وإبلاغ المرافق فوراً بأي حاجة لتمديد المدة", "sla": "حسب الخطة", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "إنهاء الأعمال واختبار الأنظمة المتأثرة وتسليم المساحة للمرافق بقائمة فحص", "sla": "فور الانتهاء", "where": "قائمة فحص إعادة الفتح", "kind": "step"}, {"unit": "GEN", "action": "التنظيف النهائي الشامل وإزالة الحواجز وإعادة الأثاث", "sla": "يوم", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "فحص النظافة وإجازة عودة المساحة للخدمة من ناحية مكافحة العدوى", "sla": "24 ساعة", "where": "—", "kind": "decision", "role": "مكافحة العدوى"}, {"unit": "FAC", "action": "جولة إعادة الفتح المشتركة (المرافق، الصيانة، المنشأة): السلامة من الحريق، المخارج والأبواب، الكهرباء والإنارة، التكييف، الغازات الطبية، النظافة، الأجهزة؛ توقيع المحضر أو تحرير ملاحظات بمهلة", "sla": "يوم", "where": "محضر إعادة الفتح", "kind": "decision"}, {"unit": "FAC", "action": "تحديث حالة الغرفة إلى «تشغيلية»، وإبلاغ المنشأة والأقسام بإعادة الفتح، وإغلاق الطلب", "sla": "فور التوقيع", "where": "سجل المساحات", "kind": "step"}]'::jsonb,'الإغلاق الطارئ (خطر على السلامة) يُنفَّذ فوراً بقرار الصيانة أو المنشأة، ثم تُستكمل الخطوات 2 إلى 6 خلال 24 ساعة. أي تمديد للمدة يُبلَّغ للمنشأة قبل انتهاء المدة المعلنة ويُعتمد بمستوى الإغلاق نفسه (R-11).',201) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('F-02','تعطيل أنظمة السلامة من الحريق وإجراءات السلامة البديلة','FAC','["MNT", "FAC", "BEN", "GEN", "DIR"]'::jsonb,'ألا تبقى منطقة مشغولة دون حماية من الحريق إلا بإجراءات بديلة معلنة ومراقبة حتى عودة النظام.','تعطيل مخطط أو عطل في الإنذار أو الرشاشات أو مضخات الحريق أو أبواب الحريق أو مخارج الطوارئ وممراتها.','النظام المتعطل والمنطقة المتأثرة، السبب، المدة المتوقعة.','سجل تعطيل، إجراءات بديلة مطبقة، إبلاغ الجهات المعنية، سجل إعادة التشغيل والاختبار.','صفر تعطيل غير مسجل؛ عودة النظام خلال المدة المعلنة ≥ 95٪.','[{"unit": "MNT", "action": "إبلاغ المرافق فوراً بأي عطل في أنظمة الحريق، أو بخطة التعطيل المخطط ومدتها", "sla": "فوري؛ 48 ساعة للمخطط", "where": "سجل التعطيل", "kind": "step"}, {"unit": "FAC", "action": "تقييم الأثر: إذا تجاوز التعطيل 4 ساعات خلال 24 ساعة تُفعَّل إجراءات السلامة البديلة (R-14)", "sla": "ساعة", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "إبلاغ إدارة المنشأة والأقسام المتأثرة، والدفاع المدني وفق الاشتراطات", "sla": "ساعة", "where": "—", "kind": "step", "role": "مسؤول السلامة"}, {"unit": "GEN", "action": "دوريات مراقبة حريق للمنطقة، وتوفير طفايات إضافية، وإبقاء المخارج والممرات خالية", "sla": "طوال التعطيل", "where": "—", "kind": "step", "role": "الأمن والسلامة"}, {"unit": "BEN", "action": "توعية العاملين في المنطقة، وتقليل مصادر الاشتعال، ومنع الأعمال الحارة", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "الإصلاح أو إنهاء الأعمال، ثم اختبار النظام وإعادة ربطه بلوحة الإنذار", "sla": "بأسرع وقت", "where": "أمر العمل", "kind": "step"}, {"unit": "FAC", "action": "إنهاء الإجراءات البديلة، وإبلاغ الجهات بعودة النظام، وإغلاق السجل", "sla": "فور الاختبار", "where": "سجل التعطيل", "kind": "step"}, {"unit": "DIR", "action": "مراجعة سجل التعطيلات وتكرارها، وتوجيه الإجراءات التصحيحية أو الاستبدال (G-02)", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'التعطيل غير المخطط الذي يهدد السلامة يُعامل طوارئ (G-11) بالتوازي مع هذا الإجراء.',202) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('F-03','الجولات الميدانية وتفتيش بيئة الرعاية','FAC','["FAC", "MNT", "GEN", "BEN", "BME", "DIR"]'::jsonb,'اكتشاف المخاطر والعيوب قبل أن تصبح أعطالاً أو ملاحظات اعتماد، بجولات دورية موثقة لكل منشأة.','جدول الجولات السنوي (شهري للمناطق الحرجة، ربع سنوي لغيرها).','قائمة فحص الجولة الموحدة، ملاحظات الجولة السابقة.','تقرير جولة، بلاغات صيانة، ملاحظات بمسؤول ومهلة لكل منها.','تنفيذ الجولات المجدولة ≥ 95٪؛ إغلاق الملاحظات في مهلتها ≥ 85٪؛ انخفاض الملاحظات المتكررة.','[{"unit": "FAC", "action": "إعداد جدول الجولات السنوي: المناطق الحرجة شهرياً وبقية المناطق ربع سنوياً", "sla": "بداية السنة", "where": "خطة الجولات", "kind": "step"}, {"unit": "FAC", "action": "تنفيذ الجولة بفريق مشترك (المرافق، الصيانة، السلامة، مكافحة العدوى، الخدمات العامة) بقائمة فحص موحدة: السلامة من الحريق والمخارج، الكهرباء، الأسقف والجدران والأرضيات، التسربات، النظافة، المواد الخطرة، اللوحات الإرشادية", "sla": "حسب الجدول", "where": "قائمة فحص الجولة", "kind": "step"}, {"unit": "FAC", "action": "تصنيف كل ملاحظة: إصلاح فوري، بلاغ صيانة (G-05)، مشروع (G-02)، أو مسؤولية المنشأة أو الخدمات العامة", "sla": "يوم", "where": "تقرير الجولة", "kind": "decision"}, {"unit": "MNT", "action": "تنفيذ الإصلاحات المحالة", "sla": "حسب الأولوية (R-17)", "where": "أوامر العمل", "kind": "step"}, {"unit": "GEN", "action": "معالجة ملاحظات النظافة والإشغالات والمخلفات", "sla": "3 أيام", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "BEN", "action": "معالجة ملاحظات التشغيل (تخزين في الممرات، أجهزة تسد المخارج، أبواب حريق مفتوحة)", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "متابعة الإغلاق والتحقق من المعالجة في الجولة التالية", "sla": "الجولة التالية", "where": "تقرير الجولة", "kind": "step"}, {"unit": "DIR", "action": "مراجعة مؤشرات الجولات والملاحظات الأكثر تكراراً", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'نتائج الجولات مدخل رئيسي لتقييم مقاول التشغيل والصيانة (M-04) ولخطة إدارة المرافق السنوية (F-05).',203) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('F-04','سجل المواقع والأصول وحالة الغرف','FAC','["FAC", "MNT", "BME", "PRJ", "IT"]'::jsonb,'أن يكون لكل منشأة ومبنى ودور وغرفة وأصل رقم ثابت وحالة محدّثة، يُربط به كل بلاغ وأمر عمل وإغلاق ومشروع، فيُبنى تاريخ كامل لكل مكان.','الحصر الأولي، استلام مشروع، تغيير في المساحات، إضافة أصل أو إخراجه من الخدمة.','المخططات المعتمدة، بطاقات الأصول، محاضر الاستلام.','سجل محدّث، ملصقات ترميز (QR)، مخططات As-built محدّثة.','نسبة البلاغات المربوطة برقم غرفة أو أصل ≥ 95٪؛ تحديث السجل خلال أسبوع من أي تغيير.','[{"unit": "FAC", "action": "اعتماد معيار الترميز: منشأة ـ مبنى ـ دور ـ غرفة (مثال KFH-ER-GF-021)، والتصنيف الهرمي للأصول", "sla": "مرة واحدة", "where": "معيار الترميز", "kind": "step"}, {"unit": "FAC", "action": "الحصر الميداني لكل منشأة وإصدار ملصقات الغرف والأصول الرئيسية", "sla": "حسب خطة الحصر", "where": "سجل المساحات", "kind": "step"}, {"unit": "FAC", "action": "تسجيل حالة كل غرفة: تشغيلية، مغلقة للصيانة، مغلقة مؤقتاً، خارج الخدمة، تحت التطوير", "sla": "لحظي", "where": "سجل المساحات", "kind": "step"}, {"unit": "MNT", "action": "تسجيل أصول المرافق (مولدات، مضخات، وحدات تكييف، لوحات كهرباء، مصاعد) ببياناتها وجدول صيانتها الوقائية", "sla": "أسبوع من الاستلام", "where": "سجل الأصول", "kind": "step"}, {"unit": "BME", "action": "ربط الأجهزة الطبية في نظامها برقم الغرفة", "sla": "أسبوع", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "PRJ", "action": "تسليم مخططات As-built وقوائم الأصول الجديدة مع كل مشروع (G-04)", "sla": "عند الاستلام", "where": "المستندات", "kind": "step"}, {"unit": "FAC", "action": "تحديث السجل والمخططات عند أي تغيير (G-12، F-01)", "sla": "أسبوع", "where": "سجل المساحات", "kind": "step"}, {"unit": "FAC", "action": "مراجعة سنوية لدقة السجل بعينة ميدانية", "sla": "سنوياً", "where": "—", "kind": "decision"}]'::jsonb,'',204) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('F-05','خطة إدارة المرافق السنوية وتقييمها','FAC','["FAC", "MNT", "GEN", "BME", "PRJ", "DIR", "EXEC"]'::jsonb,'خطة سنوية مكتوبة لإدارة المرافق والسلامة بأهداف ومؤشرات ومسؤوليات، تُقيَّم وتُحسَّن كل عام، وتكون المرجع أمام متطلبات الاعتماد.','دورة التخطيط السنوية.','تقييم مخاطر المرافق، مؤشرات العام السابق، ملاحظات الجولات والاعتماد، تقارير الحوادث.','خطة معتمدة، سجل مخاطر، ميزانية، تقرير تقييم سنوي.','اعتماد الخطة قبل بداية السنة؛ تحقيق ≥ 80٪ من أهدافها.','[{"unit": "FAC", "action": "تقييم مخاطر المرافق لكل منشأة (الاحتمالية × الأثر): السلامة الإنشائية، الحريق، المرافق الحيوية، المواد الخطرة، الأمن", "sla": "أكتوبر", "where": "سجل المخاطر", "kind": "step"}, {"unit": "MNT", "action": "مدخلات الصيانة الوقائية والاختبارات والاستبدال (G-06، M-03)", "sla": "نوفمبر", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "مدخلات المشاريع المخططة وأثرها على المساحات والتشغيل", "sla": "نوفمبر", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "إعداد الخطة: البرامج، المسؤوليات، المؤشرات، التدريب والتمارين، بالتنسيق مع الصيانة والخدمات العامة والصيانة الطبية", "sla": "نوفمبر", "where": "خطة إدارة المرافق", "kind": "step"}, {"unit": "DIR", "action": "مراجعة الخطة والميزانية", "sla": "ديسمبر", "where": "—", "kind": "decision"}, {"unit": "EXEC", "action": "اعتماد الخطة السنوية", "sla": "ديسمبر", "where": "—", "kind": "decision"}, {"unit": "FAC", "action": "تقرير مؤشرات ربع سنوي لمدير الإدارة", "sla": "ربع سنوي", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "التقييم السنوي: ما تحقق، الفجوات، والتحسينات للعام التالي", "sla": "نهاية السنة", "where": "تقرير التقييم", "kind": "step"}]'::jsonb,'تُطابَق بنود الخطة مع معايير إدارة المرافق والسلامة المعتمدة لدى إدارة الجودة (سباهي) واشتراطات الدفاع المدني.',205) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('M-01','تصريح العمل والعزل الآمن','MNT','["MNT", "BEN", "FAC", "PRJ"]'::jsonb,'ألا تُنفَّذ أعمال عالية الخطورة إلا بتصريح مكتوب يحدد المخاطر والضوابط والمسؤول، مع عزل آمن لمصادر الطاقة.','أي عمل مذكور في R-13 من الصيانة أو مقاوليها أو مقاولي المشاريع.','وصف العمل والموقع والمدة، المنفذون ومؤهلاتهم، تقييم المخاطر، خطة العزل.','تصريح موقّع معلّق في الموقع، سجل العزل والأقفال، تصريح مغلق بعد إعادة الوضع.','100٪ من الأعمال عالية الخطورة بتصريح؛ صفر حوادث مرتبطة بالعزل؛ إغلاق التصاريح في يومها ≥ 95٪.','[{"unit": "MNT", "action": "طلب التصريح: نوع العمل، الموقع، المدة، المنفذون، المعدات", "sla": "قبل 24 ساعة", "where": "نموذج تصريح العمل", "kind": "step", "role": "المنفذ أو المقاول"}, {"unit": "MNT", "action": "مراجعة تقييم المخاطر والضوابط: طفايات، مراقب حريق، تهوية، حماية من السقوط، معدات الوقاية", "sla": "4 ساعات", "where": "نموذج تصريح العمل", "kind": "decision", "role": "مُصدر التصاريح"}, {"unit": "BEN", "action": "موافقة المنشأة عند العمل في منطقة مشغّلة أو حرجة، وتنسيق تعطيل الكواشف إن لزم (F-02)", "sla": "قبل البدء", "where": "—", "kind": "step", "role": "مسؤول السلامة / مكافحة العدوى"}, {"unit": "PRJ", "action": "مقاولو المشاريع يطبّقون النظام نفسه، ويتولى مهندس المشروع التنسيق مع مُصدر التصاريح", "sla": "قبل البدء", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "عزل مصادر الطاقة بالأقفال والبطاقات والتحقق من انعدام الجهد أو الضغط قبل البدء", "sla": "قبل البدء", "where": "سجل العزل", "kind": "step"}, {"unit": "MNT", "action": "التنفيذ مع إبقاء التصريح في الموقع، والتوقف فوراً عند تغيّر الظروف", "sla": "مدة التصريح", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "مراقبة الحريق في الأعمال الحارة حتى 30 دقيقة بعد الانتهاء", "sla": "بعد الانتهاء", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "إزالة الأقفال بعد التحقق من خلو الموقع، وإعادة التشغيل والاختبار", "sla": "فور الانتهاء", "where": "سجل العزل", "kind": "step"}, {"unit": "MNT", "action": "إغلاق التصريح بتوقيع المنفذ والمُصدر وأرشفته", "sla": "نفس اليوم", "where": "سجل التصاريح", "kind": "step", "role": "مُصدر التصاريح"}]'::jsonb,'التصريح صالح لوردية واحدة ويُجدَّد يومياً للأعمال الممتدة. لا تُزال بطاقة عزل إلا من واضعها أو بإجراء موثق يعتمده رئيس قسم الصيانة.',301) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('M-02','الإيقاف المخطط للمرافق الحيوية','MNT','["MNT", "FAC", "DIR", "BEN", "BME", "IT", "GEN"]'::jsonb,'أي إيقاف مخطط للكهرباء أو المياه أو التكييف أو الغازات الطبية أو الشبكات يُنفَّذ بإشعار كافٍ وبديل جاهز واستعادة مختبرة دون أثر على المرضى.','صيانة أو ربط أو أعمال مشروع تتطلب فصل مرفق حيوي عن منطقة مشغولة.','المرفق والمناطق والغرف المتأثرة، الموعد والمدة، خطوات الإيقاف والاستعادة.','إشعار إيقاف معتمد، بدائل مجهزة، تقرير الاستعادة.','الإشعار في مهلته 100٪؛ الالتزام بمدة الإيقاف ≥ 95٪؛ صفر أثر سريري.','[{"unit": "MNT", "action": "إعداد خطة الإيقاف: المرفق، المناطق المتأثرة، الموعد (خارج الذروة ما أمكن)، المدة، خطوات الإيقاف والاستعادة، وخطة الطوارئ إن طال الإيقاف", "sla": "7 أيام للحرجة؛ 72 ساعة لغيرها (R-15)", "where": "خطة الإيقاف", "kind": "step"}, {"unit": "FAC", "action": "مراجعة الأثر والتعارض مع الأعمال والإغلاقات الأخرى، وتأكيد الموعد", "sla": "يومان", "where": "سجل المساحات", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الإيقاف في المناطق الحرجة", "sla": "يوم عمل", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "تأكيد الموعد وتجهيز البدائل: أسطوانات أكسجين، تأجيل الإجراءات غير العاجلة، تخزين مياه، إبلاغ الطاقم", "sla": "قبل 48 ساعة", "where": "—", "kind": "step", "role": "مدير المنشأة / التمريض"}, {"unit": "BME", "action": "تحديد الأجهزة الطبية الحرجة المتأثرة وتأمين بديلها أو مصدر طاقتها", "sla": "قبل 48 ساعة", "where": "سجل الأجهزة", "kind": "step"}, {"unit": "IT", "action": "حماية الخوادم والأنظمة (UPS، إيقاف آمن)", "sla": "قبل الإيقاف", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "التواجد في المناطق المتأثرة وتنظيم الحركة", "sla": "وقت الإيقاف", "where": "—", "kind": "step", "role": "الأمن"}, {"unit": "MNT", "action": "التنفيذ بتصريح عمل (M-01) مع فريق استعادة جاهز في الموقع", "sla": "الموعد المعتمد", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "الاستعادة والتحقق من عودة المرفق في كل منطقة: القراءات، إنذارات الغازات، درجات الحرارة", "sla": "فور الانتهاء", "where": "تقرير الإيقاف", "kind": "decision"}, {"unit": "FAC", "action": "إبلاغ المنشأة بالاستعادة وأرشفة تقرير الإيقاف", "sla": "نفس اليوم", "where": "—", "kind": "step"}]'::jsonb,'الإيقاف غير المخطط يُعامل طوارئ (G-11).',302) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('M-03','الاختبارات الدورية للأنظمة الحرجة','MNT','["MNT", "FAC", "BME", "BEN", "DIR"]'::jsonb,'التأكد بالاختبار الموثق أن الأنظمة التي يعتمد عليها المرضى تعمل عند الحاجة.','جدول الاختبارات السنوي.','قائمة الأنظمة الحرجة، توصيات الصانع، الاشتراطات.','سجلات اختبار موقّعة، إجراءات تصحيحية للنتائج خارج الحدود.','إنجاز الاختبارات في موعدها 100٪؛ إغلاق الإخفاقات خلال المهلة.','[{"unit": "MNT", "action": "إعداد جدول الاختبارات: المولدات ومفاتيح تحويل الأحمال تحت حمل شهرياً، مضخات وأنظمة الحريق، إنذارات الغازات الطبية وضغوطها، المصاعد، التكييف والضغط في العمليات والعزل، UPS، خزانات المياه وجودتها", "sla": "بداية السنة", "where": "جدول الاختبارات", "kind": "step"}, {"unit": "FAC", "action": "تنسيق مواعيد الاختبارات المؤثرة على التشغيل مع المنشآت", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تنفيذ الاختبار وتسجيل القراءات (زمن التحويل، الحمل، الضغوط، درجات الحرارة)", "sla": "حسب الجدول", "where": "سجل الاختبارات", "kind": "step"}, {"unit": "MNT", "action": "أي نتيجة خارج الحدود: إصلاح فوري، أو طوارئ (G-11) إن مسّت السلامة", "sla": "فوري", "where": "أمر العمل", "kind": "decision"}, {"unit": "BME", "action": "اختبارات الأجهزة الطبية الداعمة للحياة وفق جدولها", "sla": "حسب الجدول", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "BEN", "action": "المشاركة في تمارين الإخلاء والإنذار", "sla": "نصف سنوي", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "مراجعة ملخص الاختبارات والإخفاقات", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'الدوريات المذكورة مقترحة وتُضبط وفق توصيات الصانع والاشتراطات المعتمدة.',303) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('M-04','إدارة عقود التشغيل والصيانة وتقييم المقاولين','MNT','["MNT", "FAC", "DIR", "FIN", "PROC"]'::jsonb,'أن يُدفع لمقاول التشغيل والصيانة مقابل أداء مقاس، وأن تُطبَّق الحسومات والغرامات وفق العقد.','بدء عقد تشغيل وصيانة، ونهاية كل شهر.','العقد ونطاقه ومؤشراته، سجل البلاغات وأوامر العمل، خطة الصيانة الوقائية، كشف العمالة.','تقييم شهري، محضر حسومات، مستخلص معتمد، توصية التجديد أو الإنهاء.','تقييم شهري في موعده 100٪؛ العمالة الفعلية إلى التعاقدية ≥ 95٪.','[{"unit": "MNT", "action": "استلام العقد: النطاق، المؤشرات (زمن الاستجابة، إنجاز الوقائية، العمالة، قطع الغيار)، الحسومات، وتعريف المقاول بالمنشآت والإجراءات", "sla": "بدء العقد", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "متابعة يومية للحضور والعمالة وأوامر العمل والتزام المهل", "sla": "يومياً", "where": "أوامر العمل", "kind": "step"}, {"unit": "FAC", "action": "تقييم رضا المنشآت ونتائج الجولات (F-03) كمدخل للتقييم", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "التقييم الشهري للأداء وحساب الحسومات وفق العقد", "sla": "خلال 5 أيام من نهاية الشهر", "where": "نموذج التقييم", "kind": "decision"}, {"unit": "DIR", "action": "اعتماد التقييم والحسومات", "sla": "3 أيام", "where": "—", "kind": "decision"}, {"unit": "FIN", "action": "صرف المستخلص بعد الحسومات", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تقرير أداء ربع سنوي، وتوصية قبل انتهاء العقد: تجديد، تعديل نطاق، أو إعادة طرح", "sla": "قبل الانتهاء بـ 6 أشهر", "where": "—", "kind": "decision"}, {"unit": "PROC", "action": "إجراءات التمديد أو إعادة الطرح", "sla": "حسب النظام", "where": "—", "kind": "step"}]'::jsonb,'',304) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('M-05','قطع الغيار والمخزون الاحتياطي للأنظمة الحرجة','MNT','["MNT", "DIR", "PROC", "FIN"]'::jsonb,'ألا يطول توقف نظام حرج بسبب انتظار قطعة غيار.','إعداد قائمة المخزون الاحتياطي، أو استهلاك قطعة دون الحد الأدنى.','قائمة الأنظمة الحرجة، معدلات الاستهلاك، مدد التوريد.','قائمة مخزون بحدود دنيا، طلبات تعويض، سجل استهلاك.','توفر القطع الحرجة ≥ 95٪؛ صفر توقف طويل بسبب نقص قطعة مدرجة.','[{"unit": "MNT", "action": "تحديد القطع الحرجة لكل نظام (مولدات، مضخات، ضواغط تكييف، لوحات، مصاعد) وحدها الأدنى بحسب الاستهلاك ومدة التوريد", "sla": "سنوياً", "where": "قائمة المخزون", "kind": "step"}, {"unit": "DIR", "action": "اعتماد القائمة وميزانيتها", "sla": "مع خطة الصيانة", "where": "—", "kind": "decision"}, {"unit": "MNT", "action": "تسجيل كل صرف على أمر عمل ورقم أصل", "sla": "عند الصرف", "where": "سجل المخزون", "kind": "step"}, {"unit": "MNT", "action": "طلب التعويض عند بلوغ الحد الأدنى", "sla": "فوري", "where": "—", "kind": "decision"}, {"unit": "PROC", "action": "الشراء أو التوريد وفق العقد", "sla": "حسب مدة التوريد", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "جرد ربع سنوي ومراجعة القطع الراكدة", "sla": "ربع سنوي", "where": "سجل المخزون", "kind": "step"}]'::jsonb,'إن كان العقد يُلزم المقاول بتوفير القطع، تُطابق القائمة مع التزامه وتُراقب ضمن M-04.',305) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-11','لا إغلاق بلا إشعار، ولا فتح بلا محضر','إدارة المرافق','لا تُغلق غرفة أو عيادة أو منطقة تشغيلية إلا بإشعار من المرافق وبديل متفق عليه مع المنشأة، ولا تعود للخدمة إلا بمحضر إعادة فتح وإجازة مكافحة العدوى.','["إشعار قبل 48 ساعة للإغلاق المخطط", "لوحة «مغلق للصيانة» بتاريخ العودة المتوقع", "حالة الغرفة محدّثة في السجل عند الإغلاق والفتح", "محضر إعادة فتح موقّع من المرافق والصيانة والمنشأة", "أي تمديد يُبلَّغ قبل انتهاء المدة المعلنة"]'::jsonb,'FAC','F-01','الإغلاق الطارئ يُنفَّذ فوراً ويُستكمل توثيقه خلال 24 ساعة.',11) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-12','مستويات اعتماد الإغلاق','إدارة المرافق','يتحدد من يعتمد إغلاق المساحة بمدته وحساسية المنطقة.','["حتى يومي عمل في منطقة غير حرجة: رئيس قسم المرافق بالاتفاق مع مدير المنشأة", "من 3 إلى 14 يوماً، أو أي مدة في منطقة حرجة: مدير الإدارة", "أكثر من 14 يوماً، أو إغلاق قسم كامل، أو منطقة حرجة لأكثر من 3 أيام: الإدارة التنفيذية", "المناطق الحرجة: العمليات، العناية المركزة، الطوارئ، الغسيل الكلوي، التعقيم المركزي، الولادة، المختبر وبنك الدم"]'::jsonb,'DIR','F-01','المدد مقترحة وتُضبط بقرار الإدارة.',12) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-13','تصريح العمل إلزامي للأعمال عالية الخطورة','إدارة المرافق','لا يبدأ عمل عالي الخطورة دون تصريح عمل ساري وعزل آمن، ويسري ذلك على الصيانة ومقاوليها ومقاولي المشاريع.','["الأعمال الحارة: لحام، قطع، تجليخ", "الأعمال الكهربائية التي تتطلب عزلاً أو قرب دوائر حية", "العمل على ارتفاع أكثر من مترين أو على الأسطح", "الأماكن المحصورة: خزانات، غرف تفتيش، مجاري هواء", "فتح الأسقف المستعارة في المناطق الحرجة", "أعمال الغازات الطبية", "أي تعطيل لأنظمة الحريق (F-02)"]'::jsonb,'MNT','M-01','',13) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-14','تعطيل أنظمة الحريق يستلزم إجراءات بديلة','إدارة المرافق','أي تعطيل لنظام إنذار أو إطفاء أو باب حريق أو مخرج يُسجَّل فوراً، وإذا تجاوز 4 ساعات خلال 24 ساعة تُطبَّق إجراءات السلامة البديلة ويُبلَّغ الدفاع المدني وفق الاشتراطات.','["سجل تعطيل لكل حالة", "مراقبة حريق مستمرة للمنطقة", "طفايات إضافية ومخارج خالية", "منع الأعمال الحارة في المنطقة", "اختبار النظام قبل إنهاء الإجراءات البديلة"]'::jsonb,'FAC','F-02','المدة مقترحة وتُطابق مع اشتراطات الدفاع المدني.',14) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-15','الإيقاف المخطط للمرافق بإشعار مسبق وبديل جاهز','إدارة المرافق','لا يُفصل مرفق حيوي (كهرباء، مياه، تكييف، غازات طبية، شبكة) عن منطقة مشغولة إلا بخطة معتمدة وإشعار مسبق.','["72 ساعة للمناطق غير الحرجة", "7 أيام للمناطق الحرجة مع اعتماد مدير الإدارة", "التنفيذ خارج الذروة ما أمكن", "بديل جاهز قبل البدء (أكسجين، طاقة، مياه)", "فريق استعادة في الموقع طوال الإيقاف"]'::jsonb,'MNT','M-02','المهل مقترحة.',15) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-16','كل بلاغ على رقم غرفة أو أصل','إدارة المرافق','لا يُفتح أمر عمل ولا يُسجَّل إغلاق إلا مربوطاً برقم غرفة أو أصل من السجل، حتى يُبنى تاريخ كل مكان وأصل.','["ترميز ثابت: منشأة ـ مبنى ـ دور ـ غرفة", "ملصق QR على الغرف والأصول الرئيسية", "حالة الغرفة تُحدَّث عند الإغلاق والفتح", "السجل يُحدَّث خلال أسبوع من أي تغيير"]'::jsonb,'FAC','F-04','',16) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-17','أولوية البلاغ بأثره لا بمن رفعه','إدارة المرافق','تُحدَّد أولوية بلاغ المرافق بأثره على السلامة والمريض والتشغيل.','["طارئ: خطر على السلامة أو توقف منطقة حرجة — استجابة خلال ساعتين ومعالجة مؤقتة فوراً", "عاجل: يؤثر على تشغيل منطقة أو راحة المرضى — خلال 24 ساعة", "عادي: لا يؤثر على التشغيل — خلال 5 أيام عمل", "مخطط: يُجدول مع الصيانة الوقائية أو إغلاق مخطط"]'::jsonb,'MNT','G-05','',17) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-18','الدفع لمقاول التشغيل مقابل أداء مقاس','إدارة المرافق','لا يُعتمد مستخلص عقد التشغيل والصيانة دون تقييم شهري موثق وحسومات محسوبة وفق العقد.','["تقييم خلال 5 أيام من نهاية الشهر", "مطابقة العمالة الفعلية بالتعاقدية", "إنجاز الوقائية والتزام المهل من سجل أوامر العمل", "رضا المنشآت ونتائج الجولات مدخل للتقييم"]'::jsonb,'MNT','M-04','',18) on conflict (code) do nothing;
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ح. إدارة المرافق والتشغيل','طلب إغلاق غرفة أو عيادة أو منطقة لأعمال صيانة أو مشروع (F-01)','{"MNT": "R", "PRJ": "R", "FAC": "V"}'::jsonb,31 where not exists (select 1 from public.gov_activities where scope='units' and title='طلب إغلاق غرفة أو عيادة أو منطقة لأعمال صيانة أو مشروع (F-01)');
