insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'MNT','FAC','عند الحاجة لإغلاق مساحة لأعمال صيانة','طلب إغلاق: الغرف، المدة، الأنظمة المعزولة','قبل 5 أيام عمل','F-01','',18 where not exists (select 1 from public.gov_handoffs where from_unit='MNT' and to_unit='FAC' and trigger='عند الحاجة لإغلاق مساحة لأعمال صيانة');
