insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'MNT','FAC','انتهاء الأعمال في مساحة مغلقة','المساحة مختبرة مع قائمة فحص إعادة الفتح','فور الانتهاء','F-01','',21 where not exists (select 1 from public.gov_handoffs where from_unit='MNT' and to_unit='FAC' and trigger='انتهاء الأعمال في مساحة مغلقة');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'FAC','BEN','إعادة فتح المساحة','محضر إعادة الفتح وحالة الغرفة «تشغيلية»','فور التوقيع','F-01','',22 where not exists (select 1 from public.gov_handoffs where from_unit='FAC' and to_unit='BEN' and trigger='إعادة فتح المساحة');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'MNT','FAC','تعطل نظام حريق أو تعطيله','سجل التعطيل والمدة المتوقعة','فوري','F-02','',23 where not exists (select 1 from public.gov_handoffs where from_unit='MNT' and to_unit='FAC' and trigger='تعطل نظام حريق أو تعطيله');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'MNT','BEN','إيقاف مخطط لمرفق حيوي','خطة الإيقاف والبدائل المطلوبة','72 ساعة؛ 7 أيام للحرجة','M-02','',24 where not exists (select 1 from public.gov_handoffs where from_unit='MNT' and to_unit='BEN' and trigger='إيقاف مخطط لمرفق حيوي');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف أغلق عيادة أو غرفة للصيانة؟','الإجراء F-01: ترفع الصيانة (أو مهندس المشروع) طلب إغلاق قبل 5 أيام عمل بأرقام الغرف والمدة، فتصنّفه المرافق وتحدد من يعتمده وفق R-12، وتتفق المنشأة على البديل، وتقيّم مكافحة العدوى فئة ICRA. ثم يصدر إشعار الإغلاق قبل 48 ساعة، وتُخلى الأجهزة والأثاث وتُركّب الحواجز ولوحة «مغلق للصيانة»، وتُحدَّث حالة الغرفة في السجل.','["F-01", "R-11", "R-12"]'::jsonb,'',14 where not exists (select 1 from public.gov_faq where q='كيف أغلق عيادة أو غرفة للصيانة؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف تعود الغرفة للخدمة بعد الصيانة؟','بعد الاختبار والتنظيف النهائي وإجازة مكافحة العدوى، تُجرى جولة إعادة فتح مشتركة (المرافق والصيانة والمنشأة) بقائمة فحص، ولا تعود الغرفة «تشغيلية» إلا بمحضر موقّع (R-11).','["F-01", "R-11"]'::jsonb,'',15 where not exists (select 1 from public.gov_faq where q='كيف تعود الغرفة للخدمة بعد الصيانة؟');
insert into public.gov_faq(q,a,links,action,sort) select 'متى أحتاج تصريح عمل؟','في كل عمل عالي الخطورة: الأعمال الحارة، الكهرباء التي تتطلب عزلاً، الارتفاعات، الأماكن المحصورة، فتح الأسقف في المناطق الحرجة، الغازات الطبية، وتعطيل أنظمة الحريق (R-13). التصريح يصدر وفق M-01 مع عزل آمن بالأقفال والبطاقات.','["M-01", "R-13"]'::jsonb,'',16 where not exists (select 1 from public.gov_faq where q='متى أحتاج تصريح عمل؟');
insert into public.gov_faq(q,a,links,action,sort) select 'ماذا نفعل إذا تعطّل الإنذار أو الرشاشات؟','يُسجَّل التعطيل فوراً وتُبلَّغ المرافق، وإذا تجاوز 4 ساعات خلال 24 ساعة تُطبَّق إجراءات السلامة البديلة: مراقبة حريق، طفايات إضافية، مخارج خالية، منع الأعمال الحارة، وإبلاغ الدفاع المدني (F-02، R-14).','["F-02", "R-14"]'::jsonb,'',17 where not exists (select 1 from public.gov_faq where q='ماذا نفعل إذا تعطّل الإنذار أو الرشاشات؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف نوقف الكهرباء أو المياه أو الأكسجين عن منطقة؟','بخطة إيقاف وفق M-02 بإشعار 72 ساعة (7 أيام للمناطق الحرجة مع اعتماد مدير الإدارة)، وبدائل جاهزة قبل البدء، وفريق استعادة في الموقع، وتحقق من عودة المرفق في كل منطقة (R-15).','["M-02", "R-15"]'::jsonb,'',18 where not exists (select 1 from public.gov_faq where q='كيف نوقف الكهرباء أو المياه أو الأكسجين عن منطقة؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف نعرف حالة كل غرفة وأصل؟','من سجل المواقع والأصول (F-04): لكل غرفة وأصل رقم ثابت وحالة (تشغيلية، مغلقة للصيانة، خارج الخدمة…)، وكل بلاغ أو إغلاق يُربط برقمه (R-16).','["F-04", "R-16"]'::jsonb,'',19 where not exists (select 1 from public.gov_faq where q='كيف نعرف حالة كل غرفة وأصل؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف تُحدَّد أولوية بلاغ المرافق؟','بأثره لا بمن رفعه (R-17): طارئ خلال ساعتين، عاجل خلال 24 ساعة، عادي خلال 5 أيام عمل، ومخطط يُجدول مع الصيانة الوقائية.','["R-17", "G-05"]'::jsonb,'',20 where not exists (select 1 from public.gov_faq where q='كيف تُحدَّد أولوية بلاغ المرافق؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف يُقيَّم مقاول التشغيل والصيانة؟','تقييم شهري خلال 5 أيام من نهاية الشهر وفق مؤشرات العقد (الاستجابة، الوقائية، العمالة، القطع) مع رضا المنشآت ونتائج الجولات، ثم حسومات يعتمدها مدير الإدارة قبل صرف المستخلص (M-04، R-18).','["M-04", "R-18"]'::jsonb,'',21 where not exists (select 1 from public.gov_faq where q='كيف يُقيَّم مقاول التشغيل والصيانة؟');
insert into public.gov_router(key,q,opts,sort) values ('close','ما الذي تحتاج إغلاقه أو إيقافه؟','[{"t": "غرفة أو عيادة أو منطقة لأعمال صيانة أو تطوير", "out": {"proc": "F-01", "unit": "FAC", "title": "المرافق — إغلاق المساحات", "text": "طلب إغلاق قبل 5 أيام عمل بأرقام الغرف والمدة؛ المرافق تصنّفه وتتفق مع المنشأة على البديل، ولا تعود المساحة إلا بمحضر إعادة فتح."}}, {"t": "كهرباء أو مياه أو تكييف أو غازات طبية عن منطقة", "out": {"proc": "M-02", "unit": "MNT", "title": "الصيانة — الإيقاف المخطط", "text": "خطة إيقاف بإشعار 72 ساعة (7 أيام للمناطق الحرجة) مع بدائل جاهزة وفريق استعادة."}}, {"t": "نظام إنذار أو إطفاء أو باب أو مخرج حريق", "out": {"proc": "F-02", "unit": "FAC", "title": "المرافق — تعطيل أنظمة الحريق", "text": "يُسجَّل فوراً، وإذا تجاوز 4 ساعات تُطبَّق إجراءات السلامة البديلة ويُبلَّغ الدفاع المدني."}}, {"t": "عمل خطر: لحام، كهرباء، ارتفاعات، أماكن محصورة", "out": {"proc": "M-01", "unit": "MNT", "title": "الصيانة — تصريح العمل", "text": "تصريح عمل قبل 24 ساعة وعزل آمن بالأقفال والبطاقات قبل البدء."}}]'::jsonb,6) on conflict (key) do nothing;
