-- 0036: (1) توحيد اتجاه الأسهم في بيانات الحوكمة للعربية (← بدل →). (2) دليلا إجراءات قسمي المرافق (F-01..F-05) والصيانة (M-01..M-05) مع القواعد R-11..R-18 ونشاطات المصفوفة ونقاط التسليم والموجّه والأسئلة. كل الإدراجات قابلة لإعادة التشغيل ولا تلمس ما عدّله المستخدم.
update public.gov_processes set steps = replace(steps::text, '→', '←')::jsonb, notes = replace(notes, '→', '←'), goal = replace(goal, '→', '←'), trigger = replace(trigger, '→', '←')
  where steps::text like '%→%' or notes like '%→%' or goal like '%→%' or trigger like '%→%';
update public.gov_faq set a = replace(a, '→', '←'), q = replace(q, '→', '←') where a like '%→%' or q like '%→%';
update public.gov_rules set statement = replace(statement, '→', '←'), criteria = replace(criteria::text, '→', '←')::jsonb, note = replace(note, '→', '←') where statement like '%→%' or criteria::text like '%→%' or note like '%→%';
update public.gov_handoffs set trigger = replace(trigger, '→', '←'), deliverable = replace(deliverable, '→', '←'), note = replace(note, '→', '←') where trigger like '%→%' or deliverable like '%→%' or note like '%→%';
update public.gov_router set q = replace(q, '→', '←'), opts = replace(opts::text, '→', '←')::jsonb where q like '%→%' or opts::text like '%→%';
update public.gov_units set mission = replace(mission, '→', '←'), duties = replace(duties::text, '→', '←')::jsonb where mission like '%→%' or duties::text like '%→%';
update public.gov_activities set title = replace(title, '→', '←'), note = replace(note, '→', '←') where title like '%→%' or note like '%→%';
update public.gov_router set opts = opts || '[{"t": "إغلاق غرفة أو عيادة، أو إيقاف نظام، أو عمل خطر", "next": "close"}]'::jsonb where key='start' and not opts::text like '%"next": "close"%';
update public.gov_units set duties = coalesce(duties,'[]'::jsonb) || '["إغلاق المساحات للصيانة وإعادة فتحها بمحضر (F-01)", "الجولات الميدانية وخطة إدارة المرافق السنوية (F-03، F-05)"]'::jsonb where code='FAC' and not coalesce(duties,'[]'::jsonb)::text like '%إغلاق المساحات للصيا%';
update public.gov_units set duties = coalesce(duties,'[]'::jsonb) || '["تصاريح العمل والعزل الآمن والإيقاف المخطط للمرافق (M-01، M-02)", "الاختبارات الدورية للأنظمة الحرجة وتقييم مقاولي التشغيل (M-03، M-04)"]'::jsonb where code='MNT' and not coalesce(duties,'[]'::jsonb)::text like '%تصاريح العمل والعزل %';
